    #[test]
    fn test_mk_legendre_basic() {
        let c = vec![1.0, 0.0, -0.5];
        let d = [-1.0, 1.0];
        let w = [0.0, 2.0];
        let s = "P2".to_string();

        let p = mk_legendre(c.clone(), d, w, s.clone());

        assert_eq!(p.coef, c);
        assert_eq!(p.domain, d);
        assert_eq!(p.window, w);
        assert_eq!(p.symbol, s);
    }

    #[test]
    fn test_special_interval_preserved() {
        let c = vec![1.0];
        let d = [-1.0, 1.0];
        let w = [-1.0, 1.0];
        let s = "P0".to_string();

        let p = mk_legendre(c.clone(), d, w, s.clone());

        // Domain and window remain exactly [-1.0, 1.0]
        assert_eq!(p.domain, [-1.0, 1.0]);
        assert_eq!(p.window, [-1.0, 1.0]);
    }
